namespace sv_c1d059e04f2043d18e85bdc0ea6ad416.Services;

public class WarehouseState
{
    public static readonly IReadOnlyList<(string Id, string Name)> Warehouses =
    [
        ("wh-1", "Warehouse A"),
        ("wh-2", "Warehouse B"),
        ("wh-3", "Warehouse C"),
    ];

    public string CurrentWarehouseId { get; private set; } = Warehouses[0].Id;
    public string CurrentWarehouseName =>
        Warehouses.First(w => w.Id == CurrentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (CurrentWarehouseId == warehouseId) return;
        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_c1d059e04f2043d18e85bdc0ea6ad416.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activePollers;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired from a background thread — subscribers must wrap
    /// StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Ref-counted so multiple callers share one timer.
    /// </summary>
    public void StartPolling()
    {
        _activePollers++;
        if (_activePollers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component that requested polling is disposed.
    /// </summary>
    public void StopPolling()
    {
        _activePollers = Math.Max(0, _activePollers - 1);
        if (_activePollers == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Immediately refresh the alert count (e.g. after a warehouse switch).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire once immediately so subscribers get data right away.
        await RefreshAsync();

        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on StopPolling.
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

